mapper.select:
select

from ujcms_resource_category t
where t.id_ = #{id,jdbcType=BIGINT}

select

from ujcms_resource_category t
where t.site_id_ = #{siteId,jdbcType=BIGINT}

    and t.owner_id_ = #{ownerId,jdbcType=BIGINT}
    and t.owner_id_ is null

order by t.order_, t.id_

select

from ujcms_resource_category t
where t.site_id_ = #{siteId,jdbcType=BIGINT}
  and t.owner_id_ is null
  and t.name_ = #{name,jdbcType=VARCHAR}

    and t.parent_id_ = #{parentId,jdbcType=BIGINT}
    and t.parent_id_ is null

order by t.id_

select max(t.order_)
from ujcms_resource_category t
where t.site_id_ = #{siteId,jdbcType=BIGINT}

    and t.parent_id_ = #{parentId,jdbcType=BIGINT}
    and t.parent_id_ is null

select count(*)
from ujcms_resource_category t
where t.parent_id_ = #{parentId,jdbcType=BIGINT}

select count(*)
from ujcms_attachment t
where t.shared_category_id_ = #{categoryId,jdbcType=BIGINT}
